package com.cognia.api.adapter.in.web;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import com.cognia.api.TestcontainersConfiguration; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.context.jdbc.Sql; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Import(TestcontainersConfiguration.class) @Sql({"/db/seed-calculo-integral.sql","/db/seed-actividades.sql"}) class PracticeControllerTest {
	@Autowired MockMvc mvc; private static final String CONCEPT="20000000-0000-0000-0000-000000000001", ACTIVITY="40000000-0000-0000-0000-000000000001", STUDENT="30000000-0000-0000-0000-000000000001";
	@Test void queryNeverExposesCorrectnessOrSpecificFeedback() throws Exception {mvc.perform(get("/api/v1/concepts/{id}/practice-activities",CONCEPT)).andExpect(status().isOk()).andExpect(jsonPath("$[0].options[0].correct").doesNotExist()).andExpect(jsonPath("$[0].options[0].specificFeedback").doesNotExist()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("es_correcta")))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("retroalimentacion_especifica"))));}
	@Test void answersActivityAndReturnsCorrectOptionOnlyAfterAnswer() throws Exception {mvc.perform(post("/api/v1/activities/{id}/practice-attempts",ACTIVITY).header("X-Student-Id",STUDENT).contentType(MediaType.APPLICATION_JSON).content("{\"optionId\":\"50000000-0000-0000-0000-000000000001\"}")) .andExpect(status().isOk()).andExpect(jsonPath("$.correct").value(true)).andExpect(jsonPath("$.correctOptionId").value("50000000-0000-0000-0000-000000000001"));}
	@Test void missingOrInvalidStudentHeaderIsBadRequestProblem() throws Exception {mvc.perform(post("/api/v1/activities/{id}/practice-attempts",ACTIVITY).contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.title").value("Invalid request")).andExpect(jsonPath("$.status").value(400)); mvc.perform(post("/api/v1/activities/{id}/practice-attempts",ACTIVITY).header("X-Student-Id","invalid").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.title").value("Invalid request")).andExpect(jsonPath("$.status").value(400));}
	@Test void invalidPracticeRequestUses422() throws Exception {mvc.perform(post("/api/v1/activities/{id}/practice-attempts","40000000-0000-0000-0000-000000000009").header("X-Student-Id",STUDENT).contentType(MediaType.APPLICATION_JSON).content("{\"optionId\":\"50000000-0000-0000-0000-000000000009\"}" )).andExpect(status().isUnprocessableEntity()).andExpect(jsonPath("$.title").value("Invalid practice request"));}
}
